// A side pane with a Home Assistant dashboard in it, working: live states, and
// controls that do what the dashboard's own do. Lights and switches toggle,
// sliders and thermostats step, scenes and scripts run, a card's buttons
// perform their actions (asking first where the card asks first).
//
// It shows the dashboard Claude reads or saves (ha_get_dashboard,
// ha_save_dashboard), with what a save changed lit for a few seconds, or one
// picked with /dash. States are read every few seconds for the view on show;
// Markdown cards are rendered by the home, templates and all; history graphs
// become sparklines. Cards only Home Assistant can draw keep a line naming
// them and their entities.

import type { EngineInterface, Register, RenderChildren } from 'claude-code'

import type { Dash, Live, Pending } from '../types'
import { READS, brailleChart, changedCards, entitiesOf, fromBase64, glowFor, glyphFor, halfBlocks, lightColour, steady, stepFor, toggleFor, viewsOf } from './lovelace'
import type { Card, Row, ServiceCall, View } from './lovelace'

const PANE = 'vome-dash'
/**
 * Vome rate-limits each Home Assistant endpoint per key (500 an hour), and Claude's own reads share
 * it. So states are read every 10 s, and only while the pane is on show: at most 360 an hour.
 */
const STATE_MS = 10_000
/** A refused read (the hourly limit) pauses the pane's reads this long. */
const BACKOFF_MS = 5 * 60_000
const TEMPLATE_MS = 60_000
const HISTORY_MS = 60_000
const LIT_MS = 8_000
const CONFIRM_MS = 6_000
const MAX_ENTITIES = 80

const dash = { plugin: 'vome-dash', key: 'dash' } as const
const view = { plugin: 'vome-dash', key: 'view' } as const
const states = { plugin: 'vome-dash', key: 'states' } as const
const lit = { plugin: 'vome-dash', key: 'lit' } as const
const rendered = { plugin: 'vome-dash', key: 'rendered' } as const
const history = { plugin: 'vome-dash', key: 'history' } as const
const confirm = { plugin: 'vome-dash', key: 'confirm' } as const
const choices = { plugin: 'vome-dash', key: 'choices' } as const
const pending = { plugin: 'vome-dash', key: 'pending' } as const
const sidebarOpen = { plugin: 'vome-dash', key: 'sidebarOpen' } as const
const frames = { plugin: 'vome-dash', key: 'frames' } as const
/** A camera's frame is fetched this often while it is on show. */
const FRAME_EVERY_MS = 30_000
/** How long a press waits to see its device change, how often it looks, how long the outcome stays. */
const WATCH_MS = 8_000
/** After a press, the device is looked at this long after it, then no more. */
const WATCH_AT_MS = [1_000, 2_500, 5_000, 8_000]
const WATCH_EVERY_MS = 500
const OUTCOME_MS = 3_000
/** The sidebar's narrowest and widest: it sizes itself to the longest title between them. */
const SIDEBAR_MIN = 16
const SIDEBAR_MAX = 30
const blocked = { plugin: 'vome-dash', key: 'blocked' } as const
const note = { plugin: 'vome-dash', key: 'note' } as const

let isPolling = false
/** Reads paused until then: the hourly limit was hit. */
let pausedUntil = 0
let lastFrames = 0
/** The card width last drawn, for the size of camera frames and the points in a chart. */
let lastCardWidth = 40
/** The MCP has no ha_camera_frame, or no max_points on ha_get_history: ask the older way. */
let hasMaxPoints = true
/** A camera frame failed (an older MCP, a key without Cameras): ask again after this. */
let framesRetryAt = 0
/** The MCP has ha_view_snapshot: one call a refresh. False after it is found missing, until a reload. */
let hasSnapshot = true
/** Live states: one waiting read at a time while the pane is on show (ha_watch_states). */
let isWatching = false
/** The watch has answered at least once: states come by it, so the snapshot need not read them. */
let isWatchLive = false
/** The MCP or the home cannot watch (no tool, no component link): poll, and try again after this. */
let watchRetryAt = 0
let lastTemplates = 0
let lastHistory = 0
let settingsFile = '~/.claude/settings.json'
/** The last press, so Retry can make it again once it is allowed. */
let lastCall: { server: string; call: ServiceCall } | null = null

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'dash', description: 'Show a Home Assistant dashboard, working, in a side pane', argumentHint: '[dashboard url_path]' })
    const configDir = (await $.env.get('CLAUDE_CONFIG_DIR')) ?? `${(await $.env.get('HOME')) ?? '~'}/.claude`
    settingsFile = `${configDir.replace(/\/+$/, '')}/settings.json`
    $.clock.every(STATE_MS, () => void poll($))
    $.clock.every(WATCH_EVERY_MS, () => void watchPresses($))
    return next(e)
  })

  on('command.run', { command: 'dash' }, async ($, e) => {
    const wanted = e.args.trim()
    const current = (await $.state.get(dash)).value ?? null
    const server = current?.server ?? (await dashServers($))[0]
    if (!server) return { text: 'No connected MCP server has ha_get_dashboard yet: connect Home Assistant through Vome first (vome-connect).' }
    const opened = await $.ui.open({ id: PANE, title: 'Dashboard' })
    if (wanted) void loadDashboard($, server, wanted)
    else void listDashboards($, server)
    return { text: opened.isPlaced ? (wanted ? `Opening ${wanted} in the pane.` : "Listing the home's dashboards in the pane.") : `The dashboard pane is not drawn here: ${opened.reason}.` }
  })

  on('tool.call', async ($, e, next) => {
    const match = /^mcp__(.+)__(ha_get_dashboard|ha_save_dashboard|ha_list_dashboards)$/.exec(e.tool)
    if (!match?.[1] || !match[2]) return next(e)
    const server = match[1]
    const args = e as unknown as { url_path?: unknown; config?: unknown }
    const ran = await next(e)
    if (ran.deny !== undefined || ran.isError) return ran

    if (match[2] === 'ha_get_dashboard') {
      const body = parseJson(ran.text ?? '')
      if (body && body.config && typeof body.config === 'object') {
        await showDashboard($, server, String(body.url_path ?? args.url_path ?? 'lovelace'), body.config as Record<string, unknown>)
      }
    } else if (match[2] === 'ha_save_dashboard' && args.config && typeof args.config === 'object') {
      const before = (await $.state.get(dash)).value ?? null
      const urlPath = String(args.url_path ?? 'lovelace')
      const config = args.config as Record<string, unknown>
      if (before && before.urlPath === urlPath) await $.state.set(lit, { keys: [...changedCards(before.config, config)], at: Date.now() })
      await showDashboard($, server, urlPath, config)
    } else if (match[2] === 'ha_list_dashboards') {
      await setChoices($, ran.text ?? '')
    }
    return ran
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text, Button, Code, Markdown } = $.ui.resolve(e)
    const settingsLink = <Markdown text={`[${settingsFile}](file://${settingsFile})`} />
    const current = (await $.state.get(dash)).value ?? null
    const shownView = (await $.state.get(view)).value ?? 0
    const live = (await $.state.get(states)).value ?? {}
    const lighting = (await $.state.get(lit)).value ?? null
    const texts = (await $.state.get(rendered)).value ?? {}
    const series = (await $.state.get(history)).value ?? {}
    const asking = (await $.state.get(confirm)).value ?? null
    const picking = (await $.state.get(choices)).value ?? null
    const refusal = (await $.state.get(blocked)).value ?? null
    const message = (await $.state.get(note)).value ?? null
    const presses = (await $.state.get(pending)).value ?? {}
    const isMenuOpen = (await $.state.get(sidebarOpen)).value ?? false
    const pictures = (await $.state.get(frames)).value ?? {}
    const width = Math.max(30, e.props.bodyColumns)
    const isLit = (key: string) => lighting !== null && Date.now() - lighting.at < LIT_MS && lighting.keys.some(k => key === k || key.startsWith(`${k}/`))

    const help = refusal ? (
      <Box flexDirection="column" borderStyle="round" borderColor="warning" paddingX={1} marginTop={1}>
        {refusal.tool === 'ha_call_service' ? (
          <Text color="warning" wrap="wrap">
            Auto mode refused the press. Pressing a control here calls ha_call_service, and allowing that by name would
            let Claude change things without asking too. Switch auto mode off to use the controls, or allow it in
            {' '}{settingsFile} if you are happy with that:
          </Text>
        ) : (
          <Text color="warning" wrap="wrap">
            Auto mode refused the pane's read of live states. Add these to permissions.allow in {settingsFile}; they only read:
          </Text>
        )}
        {settingsLink}
        <Code source={refusal.tool === 'ha_call_service' ? `"mcp__${refusal.server}__ha_call_service"` : READS.map(t => `"mcp__${refusal.server}__${t}"`).join(',\n')} />
        <Box flexDirection="row" gap={2}>
          <Button
            key="copy-rule"
            hotkey="c"
            onPress={press =>
              $.ui.copy({
                text: refusal.tool === 'ha_call_service' ? `"mcp__${refusal.server}__ha_call_service"` : READS.map(t => `"mcp__${refusal.server}__${t}"`).join(',\n'),
                surface: press.surface,
              })
            }
          >
            Copy
          </Button>
          <Button
            key="retry"
            hotkey="t"
            onPress={async () => {
              await $.state.set(blocked, null)
              // Allowed since: nothing stays switched off for having been refused once.
              hasSnapshot = true
              hasMaxPoints = true
              framesRetryAt = 0
              watchRetryAt = 0
              if (refusal.tool === 'ha_call_service' && lastCall) await callService($, lastCall.server, lastCall.call)
              else void poll($, true)
            }}
          >
            {refusal.tool === 'ha_call_service' ? 'Retry the press' : 'Retry'}
          </Button>
          <Button key="dismiss-rule" dimColor onPress={() => $.state.set(blocked, null)}>
            Dismiss
          </Button>
        </Box>
      </Box>
    ) : null

    const picker = picking ? (
      <Box flexDirection="column" marginTop={1}>
        <Text bold>Dashboards</Text>
        <Box flexDirection="row" flexWrap="wrap" gap={1}>
          {picking.map(choice => (
            <Button
              key={`pick-${choice.urlPath}`}
              onPress={async () => {
                await $.state.set(choices, null)
                const server = current?.server ?? (await dashServers($))[0]
                if (server) await loadDashboard($, server, choice.urlPath)
              }}
            >
              {choice.title}
            </Button>
          ))}
        </Box>
      </Box>
    ) : null

    if (!current) {
      return (
        <Box flexDirection="column">
          <Text dimColor wrap="wrap">
            No dashboard yet. It appears here, working, when Claude reads or saves one, or pick one with /dash.
          </Text>
          {picker}
          {message ? <Text color="warning" wrap="wrap">{message}</Text> : null}
          {help}
        </Box>
      )
    }

    const views = viewsOf(current.config)
    const index = Math.min(shownView, Math.max(0, views.length - 1))
    const shown: View | undefined = views[index]
    // The home's dashboards down the left, as Home Assistant's sidebar has them, until one is picked.
    const hasMenu = (picking?.length ?? 0) > 1
    const isSidebar = isMenuOpen && hasMenu && width >= 70
    // Wide enough for the longest title, its marker and a button's brackets, inside the border.
    const longest = Math.max(10, ...(picking ?? []).map(choice => choice.title.length))
    const sidebarWidth = Math.min(SIDEBAR_MAX, Math.max(SIDEBAR_MIN, longest + 2 + 4 + 4))
    const mainWidth = isSidebar ? width - sidebarWidth - 1 : width
    // Columns as Home Assistant's desktop layout has them: as many as fit, cards stacked in each.
    const columns = mainWidth >= 120 ? 3 : mainWidth >= 72 ? 2 : 1
    const cardWidth = columns > 1 ? Math.floor((mainWidth - (columns - 1)) / columns) : mainWidth
    lastCardWidth = cardWidth
    /** What a control's press is doing, for the row it is on. */
    const pressOf = (prefix: string): Pending | undefined =>
      Object.entries(presses)
        .filter(([key]) => key === prefix || key.startsWith(`${prefix}/`))
        .map(([, p]) => p)
        .sort((a, b) => b.at - a.at)[0]
    const spinner = '⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏'[Math.floor(Date.now() / 120) % 10]
    const pressNote = (p: Pending | undefined) =>
      !p ? null : p.phase === 'sending' ? (
        <Text color="warning">{spinner} sending</Text>
      ) : p.phase === 'sent' ? (
        <Text color="suggestion">{spinner} sent, waiting</Text>
      ) : p.phase === 'done' ? (
        <Text color="success">✓</Text>
      ) : p.phase === 'quiet' ? (
        <Text color="warning">no change seen</Text>
      ) : (
        <Text color="error">✗ failed</Text>
      )

    const press = async (key: string, call: ServiceCall) => {
      if (call.confirm && !(asking && asking.key === key && asking.until > Date.now())) {
        await $.state.set(confirm, { key, until: Date.now() + CONFIRM_MS })
        return
      }
      await $.state.set(confirm, null)
      await pressAndWatch($, current.server, key, call)
    }

    const entityRow = (row: Extract<Row, { kind: 'entity' }>, key: string) => {
      const now: Live | undefined = live[row.entity]
      const state = now?.state ?? '…'
      const attributes = now?.attributes ?? {}
      const name = row.name ?? (typeof attributes.friendly_name === 'string' ? steady(attributes.friendly_name) : row.entity)
      const unit = typeof attributes.unit_of_measurement === 'string' ? ` ${attributes.unit_of_measurement}` : ''
      const toggle = toggleFor(row.entity)
      const down = now ? stepFor(row.entity, attributes, state, -1) : null
      const up = now ? stepFor(row.entity, attributes, state, 1) : null
      const isOn = state === 'on'
      const shownState = row.entity.startsWith('light.') && isOn && typeof attributes.brightness === 'number' ? `on ${Math.round((attributes.brightness / 255) * 100)}%` : `${formatState(state)}${unit}`
      const going = pressOf(key)
      const isFresh = going?.phase === 'done'
      // A light that is on glows in its own colour, as brightly as it is lit.
      const glow = glowFor(row.entity, state, attributes)
      const isLight = row.entity.startsWith('light.') && isOn
      // A slider's position, as Home Assistant draws its bar.
      const min = typeof attributes.min === 'number' ? attributes.min : null
      const max = typeof attributes.max === 'number' ? attributes.max : null
      const isSlider = /^(input_number|number)\./.test(row.entity) && min !== null && max !== null && max > min
      const slider = isSlider ? sliderBar((Number(state) - min!) / (max! - min!), 8) : null
      return (
        <Box flexDirection="row" gap={1} backgroundColor={glow ?? undefined}>
          <Box flexGrow={1} flexShrink={1} minWidth={4} overflow="hidden">
            <Text wrap="truncate-end" backgroundColor={glow ?? undefined}>
              {glyphFor(row.entity, attributes, row.icon)} <Text bold={isLight}>{name}</Text>
            </Text>
          </Box>
          <Box flexDirection="row" gap={1} flexShrink={0}>
            {slider ? <Text color="warning">{slider}</Text> : null}
            {pressNote(going)}
            <Text
              color={isFresh ? 'success' : state === 'unavailable' ? 'error' : isLight ? lightColour(attributes) : isOn ? 'warning' : undefined}
              backgroundColor={glow ?? undefined}
              bold={isFresh || isLight}
              dimColor={state === 'off' && !isFresh}
            >
              {shownState}
            </Text>
            {down ? (
              <Button key={`${key}/down`} dimColor onPress={() => press(`${key}/down`, down)}>
                −
              </Button>
            ) : null}
            {up ? (
              <Button key={`${key}/up`} dimColor onPress={() => press(`${key}/up`, up)}>
                +
              </Button>
            ) : null}
            {toggle && toggle.service === 'toggle' ? (
              <Button key={`${key}/toggle`} dimColor={!isOn} onPress={() => press(`${key}/toggle`, toggle)}>
                {isOn ? '━━●' : '○━━'}
              </Button>
            ) : toggle ? (
              <Button key={`${key}/run`} onPress={() => press(`${key}/run`, toggle)}>
                Run
              </Button>
            ) : null}
          </Box>
        </Box>
      )
    }

    /** An entities card's header switch: all on if any is off, else all off, as Home Assistant's does. */
    const headerToggle = (card: Card): RenderChildren => {
      if (card.type !== 'entities' || !card.headerToggle) return null
      const ids = card.rows.flatMap(row => (row.kind === 'entity' && toggleFor(row.entity)?.service === 'toggle' ? [row.entity] : []))
      if (ids.length < 2) return null
      const anyOff = ids.some(id => live[id]?.state !== 'on')
      const key = `${card.key}/all`
      return (
        <Box flexDirection="row" gap={1} flexShrink={0}>
          {pressNote(pressOf(key))}
          <Button
            key={key}
            dimColor={anyOff}
            onPress={() => press(key, { domain: 'homeassistant', service: anyOff ? 'turn_on' : 'turn_off', target: { entity_id: ids } })}
          >
            {anyOff ? '○━━' : '━━●'}
          </Button>
        </Box>
      )
    }

    // A card is as wide as the room it is given; one inside a stack gets what is left inside its
    // parent's border and padding (four cells), or it spills out over the edge.
    const drawCard = (card: Card, cardKey: string, room = cardWidth): RenderChildren => {
      const inner = Math.max(8, room - 4)
      const titleColour = isLit(card.key) ? 'suggestion' : undefined
      const body: RenderChildren[] = []
      if (card.markdown !== null) {
        const text = texts[card.key] ?? card.markdown.replace(/\{%[\s\S]*?%\}|\{\{[\s\S]*?\}\}/g, '…')
        body.push(<Markdown text={text} />)
      }
      if (card.camera) {
        // The camera's still in half blocks: two pixels a cell, in its own colours.
        const frame = pictures[card.key]
        const name = typeof live[card.camera]?.attributes.friendly_name === 'string' ? (live[card.camera]!.attributes.friendly_name as string) : card.camera
        if (frame && e.surface === 'terminal') {
          const { Raster } = $.ui.resolve(e)
          const art = halfBlocks(fromBase64(frame.rgb), frame.width, frame.height)
          body.push(<Raster key={`frame-${card.key}`} columns={art.columns} rows={art.rows} cells={art.cells} />)
        } else {
          body.push(<Text dimColor>{frame ? `📷 ${name}: the picture shows in a terminal` : `📷 ${name}: fetching…`}</Text>)
        }
        if (frame) body.push(<Text dimColor wrap="truncate-end">📷 {name} · {since(frame.at)}</Text>)
      }
      if (card.hours !== null) {
        for (const row of card.rows) {
          if (row.kind !== 'entity') continue
          const points = series[card.key]?.[row.entity] ?? []
          const numbers = points.filter((p): p is number => typeof p === 'number')
          const name = row.name ?? row.entity
          const unit = typeof live[row.entity]?.attributes.unit_of_measurement === 'string' ? ` ${live[row.entity]!.attributes.unit_of_measurement}` : ''
          body.push(
            <Text wrap="truncate-end">
              {name}
              <Text dimColor>
                {'  '}
                {formatState(live[row.entity]?.state ?? '')}
                {unit}
                {numbers.length > 1 ? `  (${formatState(String(Math.min(...numbers)))}–${formatState(String(Math.max(...numbers)))})` : ''}
              </Text>
            </Text>,
          )
          if (numbers.length > 1) {
            for (const line of brailleChart(numbers, Math.max(10, inner), 3)) {
              body.push(<Text color="suggestion">{line}</Text>)
            }
          } else {
            body.push(<Text dimColor>{points.length > 0 ? [...new Set(points.map(String))].slice(-4).join(' → ') : '…'}</Text>)
          }
        }
      } else if (card.type === 'glance') {
        // A glance card as Home Assistant draws it: a row of icons, each with its name and state under it.
        body.push(
          <Box flexDirection="row" flexWrap="wrap" columnGap={1}>
            {card.rows.map((row, i) => {
              if (row.kind !== 'entity') return null
              const now = live[row.entity]
              const attributes = now?.attributes ?? {}
              const state = now?.state ?? '…'
              const name = row.name ?? (typeof attributes.friendly_name === 'string' ? steady(attributes.friendly_name) : row.entity)
              const toggle = toggleFor(row.entity)
              const key = `${cardKey}/r${i}`
              const isOn = state === 'on'
              return (
                <Box flexDirection="column" alignItems="center" width={12} backgroundColor={glowFor(row.entity, state, attributes) ?? undefined}>
                  <Text wrap="truncate-end" dimColor={!isOn}>
                    {name}
                  </Text>
                  <Text>{glyphFor(row.entity, attributes, row.icon)}</Text>
                  <Text color={isOn ? 'warning' : undefined} dimColor={!isOn}>
                    {formatState(state)}
                  </Text>
                  {toggle && toggle.service === 'toggle' ? (
                    <Button key={`${key}/toggle`} dimColor={!isOn} onPress={() => press(`${key}/toggle`, toggle)}>
                      {isOn ? '━━●' : '○━━'}
                    </Button>
                  ) : null}
                  {pressNote(pressOf(key))}
                </Box>
              )
            })}
          </Box>,
        )
      } else {
        card.rows.forEach((row, i) => {
          const key = `${cardKey}/r${i}`
          if (row.kind === 'entity') body.push(entityRow(row, key))
          else if (row.kind === 'text') body.push(<Text dimColor>{row.text}</Text>)
          else {
            const isAsking = asking !== null && asking.key === key && asking.until > Date.now()
            body.push(
              <Box flexDirection="row" justifyContent="space-between">
                <Text wrap="truncate-end">{isAsking ? <Text color="warning">{row.call?.confirm} Press again.</Text> : <Text>▸ {row.name}</Text>}</Text>
                <Box flexDirection="row" gap={1}>
                  {pressNote(pressOf(key))}
                  {row.call ? (
                    <Button key={key} onPress={() => press(key, row.call!)}>
                      {isAsking ? 'Yes' : 'Run'}
                    </Button>
                  ) : null}
                </Box>
              </Box>,
            )
          }
        })
      }
      if (card.isForeign) body.unshift(<Text dimColor>{card.type.replace(/^custom:/, '')} · drawn by Home Assistant</Text>)
      // A horizontal stack splits its room between its cards; the others stack them at full width.
      const across = card.type === 'horizontal-stack' || card.type === 'grid' ? Math.max(1, Math.min(card.children.length, Math.floor(inner / 24))) : 1
      const childRoom = across > 1 ? Math.floor((inner - (across - 1)) / across) : inner
      const children = card.children.map((child, i) => drawCard(child, `${cardKey}/c${i}`, childRoom))
      if (across > 1) body.push(<Box flexDirection="row" flexWrap="wrap" columnGap={1}>{children}</Box>)
      else body.push(...children)
      if (card.isForeign && card.rows.length === 0 && card.children.length === 0 && !card.title) return null
      return (
        <Box flexDirection="column" borderStyle="round" borderColor={titleColour ?? 'subtle'} paddingX={1} width={room}>
          {card.title ? (
            <Box flexDirection="row">
              <Box flexGrow={1} flexShrink={1} overflow="hidden">
                <Text bold color={titleColour} wrap="truncate-end">
                  {card.title}
                </Text>
              </Box>
              {headerToggle(card)}
            </Box>
          ) : null}
          {body}
        </Box>
      )
    }

    const open = (urlPath: string) => async () => {
      await $.state.set(sidebarOpen, false)
      if (urlPath !== current.urlPath) await loadDashboard($, current.server, urlPath)
    }
    const sidebar = isSidebar ? (
      <Box flexDirection="column" width={sidebarWidth} borderStyle="round" borderColor="subtle" paddingX={1}>
        <Text dimColor>Dashboards</Text>
        {(picking ?? []).map(choice => (
          <Button key={`side-${choice.urlPath}`} dimColor={choice.urlPath !== current.urlPath} onPress={open(choice.urlPath)}>
            {fit(`${choice.urlPath === current.urlPath ? '▸ ' : ''}${choice.title}`, sidebarWidth - 8)}
          </Button>
        ))}
      </Box>
    ) : null
    // Narrow, the same as a row along the top.
    const topRow =
      isMenuOpen && hasMenu && !isSidebar ? (
        <Box flexDirection="row" flexWrap="wrap" gap={1}>
          {(picking ?? []).map(choice => (
            <Button key={`side-${choice.urlPath}`} dimColor={choice.urlPath !== current.urlPath} onPress={open(choice.urlPath)}>
              {choice.title}
            </Button>
          ))}
        </Box>
      ) : null

    const main = (
      <Box flexDirection="column" width={mainWidth}>
        {/* A fixed header: menu, the title in its own room (cut short, never wrapped), Reload. Symbols
            whose width terminals disagree on (☰, ⟳) left letters behind when the title changed. */}
        {/* paddingRight: the pane's own close cross sits on the top row's last cells. */}
        <Box flexDirection="row" gap={1} paddingRight={2}>
          {hasMenu ? (
            <Button key="menu" hotkey="m" dimColor={!isMenuOpen} onPress={() => $.state.set(sidebarOpen, !isMenuOpen)}>
              {isMenuOpen ? 'Close' : 'Dashboards'}
            </Button>
          ) : null}
          <Box flexGrow={1} flexShrink={1} minWidth={4} overflow="hidden">
            <Text bold wrap="truncate-end">
              {current.title}
            </Text>
          </Box>
          <Button
            key="reload"
            hotkey="r"
            dimColor
            onPress={() => {
              framesRetryAt = 0
              watchRetryAt = 0
              hasSnapshot = true
              hasMaxPoints = true
              return loadDashboard($, current.server, current.urlPath)
            }}
          >
            Reload
          </Button>
        </Box>
        {views.length > 1 ? (
          <Box flexDirection="row" flexWrap="wrap" gap={1}>
            {views.map((v, i) => (
              <Button key={`view-${i}`} dimColor={i !== index} onPress={() => $.state.set(view, i)}>
                {v.title}
              </Button>
            ))}
          </Box>
        ) : null}
        <Box flexDirection="row" gap={1}>
          {masonry(shown?.cards ?? [], columns).map(column => (
            <Box flexDirection="column" width={cardWidth}>
              {column.map(card => drawCard(card, card.key))}
            </Box>
          ))}
        </Box>
        {message ? <Text color="warning" wrap="wrap">{message}</Text> : null}
        {help}

      </Box>
    )

    return (
      <Box flexDirection="column">
        {topRow}
        {isSidebar ? (
          <Box flexDirection="row" gap={1}>
            {sidebar}
            {main}
          </Box>
        ) : (
          main
        )}
      </Box>
    )
  })
}

// ---------------------------------------------------------------- loading and live state

async function showDashboard($: EngineInterface, server: string, urlPath: string, config: Record<string, unknown>) {
  const before = (await $.state.get(dash)).value ?? null
  const title = typeof config.title === 'string' ? config.title : urlPath
  const next: Dash = { server, urlPath, title, config, at: Date.now() }
  if (!before || before.urlPath !== urlPath || before.server !== server) {
    await $.state.set(view, 0)
    await $.state.set(rendered, {})
    await $.state.set(history, {})
    lastTemplates = 0
    lastHistory = 0
  }
  await $.state.set(dash, next)
  await $.ui.open({ id: PANE, title: 'Dashboard' }).catch(() => undefined)
  void poll($, true)
  // The sidebar: the home's dashboards, read once per home.
  const listed = (await $.state.get(choices)).value ?? null
  if (!listed || !before || before.server !== server) void listDashboards($, server)
}

async function loadDashboard($: EngineInterface, server: string, urlPath: string) {
  const text = await callMcp($, server, 'ha_get_dashboard', { url_path: urlPath })
  const body = text ? parseJson(text) : null
  if (body && body.config && typeof body.config === 'object') await showDashboard($, server, urlPath, body.config as Record<string, unknown>)
}

async function listDashboards($: EngineInterface, server: string) {
  const text = await callMcp($, server, 'ha_list_dashboards', {})
  if (text) await setChoices($, text)
}

async function setChoices($: EngineInterface, text: string) {
  const body = parseJson(text)
  const rows = body && Array.isArray(body.dashboards) ? (body.dashboards as Record<string, unknown>[]) : []
  const list = rows
    .filter(row => typeof row.url_path === 'string')
    .map(row => ({ urlPath: String(row.url_path), title: typeof row.title === 'string' ? row.title : String(row.url_path) }))
  if (list.length > 0) await $.state.set(choices, list)
}

/** A press: the call, then a quick read of what it changed, so the pane answers at once. */
async function callService($: EngineInterface, server: string, call: ServiceCall): Promise<boolean> {
  lastCall = { server, call }
  const { confirm: _asked, ...args } = call
  void _asked
  const text = await callMcp($, server, 'ha_call_service', args)
  if (text === null) return false
  const ids = targetsOf(call)
  if (ids.length > 0) await readStates($, server, ids)
  return true
}

function targetsOf(call: ServiceCall): string[] {
  const target = call.target?.entity_id
  return Array.isArray(target) ? target : target ? [target] : []
}

/** How an entity looks, to tell that a press changed it: its state and the attributes a press moves. */
function lookOf(live: Live | undefined): string | null {
  if (!live) return null
  const a = live.attributes
  return [live.state, a.brightness, a.temperature, a.current_position, a.percentage].map(v => String(v ?? '')).join('|')
}

/**
 * A press with its outcome shown: sending, then sent once Home Assistant takes the call, then done
 * when the device is seen to change (the state flashes), or "no change seen" if it has not within a
 * few seconds. A slow device or a refused command no longer looks like a press that did nothing.
 */
async function pressAndWatch($: EngineInterface, server: string, key: string, call: ServiceCall) {
  const entity = targetsOf(call)[0] ?? null
  const before = entity ? lookOf(((await $.state.get(states)).value ?? {})[entity]) : null
  const set = async (phase: Pending['phase']) => {
    const now = (await $.state.get(pending)).value ?? {}
    await $.state.set(pending, { ...now, [key]: { phase, at: Date.now(), entity, before } })
  }
  await set('sending')
  const isSent = await callService($, server, call)
  if (!isSent) return set('failed')
  // Already changed by the read straight after the call? Done; else watch for it.
  const after = entity ? lookOf(((await $.state.get(states)).value ?? {})[entity]) : null
  await set(!entity || (after !== null && after !== before) ? 'done' : 'sent')
}

/** Presses waiting on their device: look again, settle them, and clear old outcomes. */
async function watchPresses($: EngineInterface) {
  const now = (await $.state.get(pending)).value ?? {}
  const keys = Object.keys(now)
  if (keys.length === 0) return
  const waiting = keys.filter(key => now[key]!.phase === 'sent')
  const current = (await $.state.get(dash)).value ?? null
  // Look only at the moments set for each press (1, 2.5, 5 and 8 s after it), not every tick.
  const due = waiting.filter(key => {
    const age = Date.now() - now[key]!.at
    return WATCH_AT_MS.some(at => age >= at && age < at + WATCH_EVERY_MS)
  })
  const ids = [...new Set(due.map(key => now[key]!.entity).filter((id): id is string => !!id))]
  // While a watch runs the change arrives by itself: only look when polling.
  if (current && ids.length > 0 && !isWatchLive) await readStates($, current.server, ids)
  const live = (await $.state.get(states)).value ?? {}
  const next: Record<string, Pending> = {}
  for (const key of keys) {
    const p = now[key]!
    const age = Date.now() - p.at
    void age
    if (p.phase === 'sent' && p.entity && lookOf(live[p.entity]) !== p.before) next[key] = { ...p, phase: 'done', at: Date.now() }
    else if (p.phase === 'sent' && age > WATCH_MS) next[key] = { ...p, phase: 'quiet', at: Date.now() }
    else if ((p.phase === 'done' || p.phase === 'quiet' || p.phase === 'failed') && age > OUTCOME_MS) continue
    else next[key] = p
  }
  await $.state.set(pending, next)
  $.ui.invalidate('ui.render')
}

/** States every few seconds for the view on show; templates and history less often. */
async function poll($: EngineInterface, isNow = false) {
  if (isPolling) return
  const current = (await $.state.get(dash)).value ?? null
  if (!current) return
  if ((await $.state.get(blocked)).value && !isNow) return
  if (!isNow && Date.now() < pausedUntil) return
  // Nobody is looking: read nothing. The tab behind another pane, or closed, costs no reads.
  if (!isNow && !(await isShown($))) return
  isPolling = true
  try {
    const views = viewsOf(current.config)
    const index = Math.min((await $.state.get(view)).value ?? 0, Math.max(0, views.length - 1))
    const cards = views[index]?.cards ?? []
    const ids = entitiesOf(cards).slice(0, MAX_ENTITIES)
    // States arrive by themselves while a watch runs; start one if none is.
    if (!isWatching && Date.now() >= watchRetryAt && ids.length > 0) void watchLoop($, current.server, current.urlPath, ids)
    const statesWatched = isWatchLive
    // One call for everything due this time; the separate calls only for an MCP without it.
    if (hasSnapshot && (await snapshot($, current.server, cards, statesWatched ? [] : ids, isNow))) return
    if (ids.length > 0) await readStates($, current.server, ids)
    if (isNow || Date.now() - lastTemplates > TEMPLATE_MS) {
      lastTemplates = Date.now()
      await renderTemplates($, current.server, cards)
    }
    if (isNow || Date.now() - lastHistory > HISTORY_MS) {
      lastHistory = Date.now()
      await readHistory($, current.server, cards)
    }
    if (isNow || Date.now() - lastFrames > FRAME_EVERY_MS) {
      lastFrames = Date.now()
      await readFrames($, current.server, cards)
    }
  } catch (error) {
    // Never silently: a refresh that broke says how.
    await $.state.set(note, `The dashboard could not refresh: ${firstLine(String(error))}`)
  } finally {
    isPolling = false
  }
}

/**
 * Live states while the pane is on show: wait for the next change (ha_watch_states holds the read
 * open at the sync backend, up to 20 s), apply it, wait again. Nothing is polled while it runs.
 * It ends when the pane is hidden, the dashboard or view changes, or the watch cannot run (an MCP
 * without the tool, a home without its component linked), and then the pane polls as before.
 */
async function watchLoop($: EngineInterface, server: string, urlPath: string, ids: string[]) {
  isWatching = true
  let cursor = 0
  const key = ids.join(',')
  try {
    while (true) {
      const current = (await $.state.get(dash)).value ?? null
      if (!current || current.urlPath !== urlPath || current.server !== server) return
      const views = viewsOf(current.config)
      const index = Math.min((await $.state.get(view)).value ?? 0, Math.max(0, views.length - 1))
      if (entitiesOf(views[index]?.cards ?? []).slice(0, MAX_ENTITIES).join(',') !== key) return
      if (!(await isShown($)) || (await $.state.get(blocked)).value) return
      const text = await callMcp($, server, 'ha_watch_states', { entity_ids: ids, wait_seconds: 20, cursor }, true)
      const body = text ? parseJson(text) : null
      if (!body || !Array.isArray(body.states)) {
        watchRetryAt = Date.now() + 5 * 60_000
        return
      }
      cursor = typeof body.cursor === 'number' ? body.cursor : cursor
      isWatchLive = true
      const rows = (body.states as Array<{ entity_id?: string; state?: unknown; attributes?: Record<string, unknown> }>)
        .filter(one => typeof one.entity_id === 'string')
        .map(one => (one.state === null ? { entity_id: one.entity_id, found: false, state: null } : { entity_id: one.entity_id, found: true, state: { state: one.state, attributes: one.attributes ?? {} } }))
      if (rows.length > 0) await applyStates($, rows)
      if (body.done === true) return
    }
  } finally {
    isWatching = false
    isWatchLive = false
  }
}

/** Every card of a view in one ha_view_snapshot: states always, templates, history and cameras when due. */
async function snapshot($: EngineInterface, server: string, cards: Card[], ids: string[], isNow: boolean): Promise<boolean> {
  const all: Card[] = []
  const walk = (card: Card) => {
    all.push(card)
    card.children.forEach(walk)
  }
  cards.forEach(walk)
  const wantTemplates = isNow || Date.now() - lastTemplates > TEMPLATE_MS
  const wantHistory = isNow || Date.now() - lastHistory > HISTORY_MS
  const wantFrames = (isNow || Date.now() - lastFrames > FRAME_EVERY_MS) && Date.now() >= framesRetryAt
  const templates = wantTemplates
    ? Object.fromEntries(all.filter(c => c.markdown !== null && /\{\{|\{%/.test(c.markdown)).slice(0, 10).map(c => [c.key, c.markdown!]))
    : {}
  const points = Math.max(20, Math.min(400, (lastCardWidth - 4) * 2))
  const graphs = wantHistory
    ? all
        .filter(c => c.hours !== null)
        .slice(0, 8)
        .map(c => ({ key: c.key, entity_ids: c.rows.flatMap(r => (r.kind === 'entity' ? [r.entity] : [])).slice(0, 20), hours: c.hours ?? 24, max_points: points }))
        .filter(h => h.entity_ids.length > 0)
    : []
  const width = Math.max(16, Math.min(160, lastCardWidth - 4))
  const cameras = wantFrames ? all.filter(c => c.camera).slice(0, 4).map(c => ({ key: c.key, entity_id: c.camera!, width, height: width })) : []
  const text = await callMcp($, server, 'ha_view_snapshot', {
    ...(ids.length > 0 ? { entity_ids: ids } : {}),
    ...(Object.keys(templates).length > 0 ? { templates } : {}),
    ...(graphs.length > 0 ? { history: graphs } : {}),
    ...(cameras.length > 0 ? { frames: cameras } : {}),
  }, true)
  const body = text ? parseJson(text) : null
  if (!body) {
    // No such tool (an older MCP): the separate calls from now on.
    if (text === null && !(await $.state.get(blocked)).value && Date.now() >= pausedUntil) hasSnapshot = false
    return !hasSnapshot ? false : true
  }
  if (wantTemplates) lastTemplates = Date.now()
  if (wantHistory) lastHistory = Date.now()
  if (wantFrames) lastFrames = Date.now()

  const got = body.states && typeof body.states === 'object' ? (body.states as Record<string, { state?: unknown; attributes?: Record<string, unknown> } | null | { error: string }>) : {}
  if ('error' in got && typeof got.error === 'string') {
    if (/\b429\b|rate.?limit|too many requests|exceeded/i.test(got.error)) await pause($)
  } else if (ids.length > 0) {
    const rows = ids.map(id => {
      const one = got[id] as { state?: unknown; attributes?: Record<string, unknown> } | null | undefined
      return one ? { entity_id: id, found: true, state: { state: one.state, attributes: one.attributes ?? {} } } : { entity_id: id, found: false, state: null }
    })
    await applyStates($, rows)
  }
  if (body.templates && typeof body.templates === 'object') {
    const before = (await $.state.get(rendered)).value ?? {}
    const next = { ...before }
    for (const [key, value] of Object.entries(body.templates as Record<string, unknown>)) if (typeof value === 'string') next[key] = value
    await $.state.set(rendered, next)
  }
  if (body.history && typeof body.history === 'object') {
    const before = (await $.state.get(history)).value ?? {}
    const next = { ...before }
    for (const [key, value] of Object.entries(body.history as Record<string, unknown>)) {
      if (!Array.isArray(value)) continue
      const byEntity: Record<string, Array<number | string>> = {}
      for (const one of value as Array<{ entity_id?: string; points?: Array<[string, number | string]> }>) {
        if (one.entity_id && Array.isArray(one.points)) byEntity[one.entity_id] = one.points.map(([, v]) => v)
      }
      next[key] = byEntity
    }
    await $.state.set(history, next)
  }
  if (body.frames && typeof body.frames === 'object') {
    const before = (await $.state.get(frames)).value ?? {}
    const next = { ...before }
    let problem: string | null = null
    for (const [key, value] of Object.entries(body.frames as Record<string, Record<string, unknown>>)) {
      if (typeof value.rgb === 'string' && typeof value.width === 'number' && typeof value.height === 'number') {
        next[key] = { width: value.width, height: value.height, rgb: value.rgb, at: Date.now() }
      } else if (typeof value.error === 'string') {
        problem = value.error
      }
    }
    await $.state.set(frames, next)
    if (problem) {
      framesRetryAt = Date.now() + 60_000
      await $.state.set(note, /403|camera|sensitive/i.test(problem) ? `Camera: ${problem}. Through Vome the key needs Cameras ticked under Sensitive devices.` : `Camera: ${problem}`)
    }
  }
  return true
}

async function readStates($: EngineInterface, server: string, ids: string[]) {
  const text = await callMcp($, server, 'ha_get_state', { entity_ids: ids })
  const body = text ? parseJson(text) : null
  const rows = body && Array.isArray(body.entities) ? (body.entities as Record<string, unknown>[]) : []
  await applyStates($, rows)
}

/** States as ha_get_state answers them ({entity_id, found, state: {state, attributes}}), into the pane. */
async function applyStates($: EngineInterface, rows: Record<string, unknown>[]) {
  if (rows.length === 0) return
  // Every one "not found" at once is the hourly limit talking, not a home with none of them: keep
  // what was last seen, pause the reads, and say so.
  if (rows.length > 2 && rows.every(row => row.found === false)) {
    await pause($)
    return
  }
  const before = (await $.state.get(states)).value ?? {}
  const next = { ...before }
  let isChanged = false
  for (const row of rows) {
    if (typeof row.entity_id !== 'string') continue
    // ha_get_state nests the whole state object under `state`: {entity_id, found, state: {state, attributes}}.
    const held = row.state && typeof row.state === 'object' ? (row.state as Record<string, unknown>) : row
    const value = held.state
    const state = row.found === false ? 'not found' : value === null || value === undefined ? 'unknown' : typeof value === 'object' ? 'unknown' : String(value)
    const attributes = held.attributes && typeof held.attributes === 'object' ? (held.attributes as Record<string, unknown>) : {}
    const was = before[row.entity_id]
    if (!was || was.state !== state || JSON.stringify(was.attributes) !== JSON.stringify(attributes)) isChanged = true
    next[row.entity_id] = { state, attributes, at: Date.now() }
  }
  if (isChanged) await $.state.set(states, next)
}

/** Markdown cards with templates, rendered by the home: the dashboard's own words, not its source. */
async function renderTemplates($: EngineInterface, server: string, cards: Card[]) {
  const all: Card[] = []
  const walk = (card: Card) => {
    if (card.markdown !== null && /\{\{|\{%/.test(card.markdown)) all.push(card)
    card.children.forEach(walk)
  }
  cards.forEach(walk)
  if (all.length === 0) return
  const before = (await $.state.get(rendered)).value ?? {}
  const next = { ...before }
  for (const card of all.slice(0, 6)) {
    const text = await callMcp($, server, 'ha_render_template', { template: card.markdown })
    if (text !== null) next[card.key] = text.replace(/\n?\[vome-instance\][^\n]*/g, '')
  }
  await $.state.set(rendered, next)
}

async function readHistory($: EngineInterface, server: string, cards: Card[]) {
  const graphs: Card[] = []
  const walk = (card: Card) => {
    if (card.hours !== null) graphs.push(card)
    card.children.forEach(walk)
  }
  cards.forEach(walk)
  if (graphs.length === 0) return
  const before = (await $.state.get(history)).value ?? {}
  const next = { ...before }
  for (const card of graphs.slice(0, 6)) {
    const ids = card.rows.flatMap(row => (row.kind === 'entity' ? [row.entity] : []))
    if (ids.length === 0) continue
    const start = new Date(Date.now() - (card.hours ?? 24) * 3600_000).toISOString()
    // As many points as the chart has dots across: a day of a sensor is thousands of states otherwise.
    const points = Math.max(20, Math.min(400, (lastCardWidth - 4) * 2))
    let text = hasMaxPoints ? await callMcp($, server, 'ha_get_history', { entity_ids: ids, start_time: start, minimal: true, max_points: points }, true) : null
    if (text === null && hasMaxPoints) {
      hasMaxPoints = false
      text = await callMcp($, server, 'ha_get_history', { entity_ids: ids, start_time: start, minimal: true })
    } else if (!hasMaxPoints) {
      text = await callMcp($, server, 'ha_get_history', { entity_ids: ids, start_time: start, minimal: true })
    }
    const body = text ? parseJson(text) : null
    const byEntity: Record<string, Array<number | string>> = {}
    const compact = body && Array.isArray(body.series) ? (body.series as unknown[]).filter((s): s is { entity_id: string; points: Array<[string, number | string]> } => !!s && typeof s === 'object' && Array.isArray((s as { points?: unknown }).points)) : []
    for (const one of compact) if (one.entity_id) byEntity[one.entity_id] = one.points.map(([, v]) => v)
    const lists = compact.length === 0 && body && Array.isArray(body.series) ? (body.series as Record<string, unknown>[][]) : []
    lists.forEach((list, i) => {
      const id = typeof list[0]?.entity_id === 'string' ? (list[0].entity_id as string) : ids[i]
      if (!id) return
      byEntity[id] = list.map(point => {
        const value = Number(point.state)
        return Number.isFinite(value) && String(point.state).trim() !== '' ? value : String(point.state)
      })
    })
    next[card.key] = byEntity
  }
  await $.state.set(history, next)
}

/** One call from the pane; a refusal shows what to allow, any other failure a note. */
async function callMcp($: EngineInterface, server: string, tool: string, args: Record<string, unknown>, isQuiet = false): Promise<string | null> {
  try {
    const result = await $.mcp.call(server, tool, args)
    const text = result.content.map(block => block.text ?? '').join('\n')
    if (result.isError && isQuiet) return null
    if (result.isError) {
      if (/\b429\b|rate.?limit|too many requests|exceeded/i.test(text)) await pause($)
      else await $.state.set(note, firstLine(text) ?? `${tool} failed.`)
      return null
    }
    // A good answer clears an old note, but not the pause's while it lasts.
    if (Date.now() >= pausedUntil && (await $.state.get(note)).value) await $.state.set(note, null)
    return text
  } catch (error) {
    if (/auto mode|classifier|permission|denied|not allowed/i.test(String(error))) {
      await $.state.set(blocked, { server, tool })
    } else {
      await $.state.set(note, firstLine(String(error)))
    }
    return null
  }
}

/** Camera stills for the picture cards on show, as small grids of pixels to draw in half blocks. */
async function readFrames($: EngineInterface, server: string, cards: Card[]) {
  if (Date.now() < framesRetryAt) return
  const cameras: Card[] = []
  const walk = (card: Card) => {
    if (card.camera) cameras.push(card)
    card.children.forEach(walk)
  }
  cards.forEach(walk)
  if (cameras.length === 0) return
  const before = (await $.state.get(frames)).value ?? {}
  const next = { ...before }
  // One pixel a cell across, two down: a cell is about twice as tall as it is wide.
  const width = Math.max(16, Math.min(160, lastCardWidth - 4))
  for (const card of cameras.slice(0, 4)) {
    const text = await callMcp($, server, 'ha_camera_frame', { entity_id: card.camera, width, height: width }, true)
    const body = text ? parseJson(text) : null
    if (!body) {
      // Not now (an older MCP, a key without Cameras): ask again in a minute, not never.
      framesRetryAt = Date.now() + 60_000
      if (!text) await $.state.set(note, 'Pictures need the MCP with ha_camera_frame, and a key with Cameras ticked.')
      continue
    }
    if (typeof body.rgb === 'string' && typeof body.width === 'number' && typeof body.height === 'number') {
      next[card.key] = { width: body.width, height: body.height, rgb: body.rgb, at: Date.now() }
    }
  }
  await $.state.set(frames, next)
}

/** Reads refused for the hourly limit: pause them, keep what was last seen, and say so. */
async function pause($: EngineInterface) {
  pausedUntil = Date.now() + BACKOFF_MS
  await $.state.set(
    note,
    "Vome's hourly limit for reading this home's states was reached (500 an hour, shared with Claude's own reads). The pane shows the last states and reads again in five minutes.",
  )
}

async function isShown($: EngineInterface): Promise<boolean> {
  try {
    return (await $.ui.panes()).some(pane => pane.id === PANE && pane.isShown && pane.isPlaced)
  } catch {
    return true
  }
}

/** Cards into columns as Home Assistant's masonry does: each to the shortest column so far. */
function masonry(cards: Card[], columns: number): Card[][] {
  const out: Card[][] = Array.from({ length: columns }, () => [])
  const heights = new Array<number>(columns).fill(0)
  for (const card of cards) {
    if (card.isForeign && card.rows.length === 0 && card.children.length === 0 && !card.title) continue
    const shortest = heights.indexOf(Math.min(...heights))
    out[shortest]!.push(card)
    heights[shortest]! += heightOf(card)
  }
  return out.filter(column => column.length > 0)
}

function heightOf(card: Card): number {
  const own = 2 + (card.title ? 1 : 0) + (card.markdown !== null ? Math.ceil(card.markdown.length / 50) + 1 : 0) + card.rows.length * (card.hours !== null ? 4 : 1)
  return own + card.children.reduce((sum, child) => sum + heightOf(child), 0)
}

// ---------------------------------------------------------------- small things

async function dashServers($: EngineInterface): Promise<string[]> {
  return (await $.tool.list())
    .map(tool => /^mcp__(.+)__ha_get_dashboard$/.exec(tool.name)?.[1])
    .filter((server): server is string => !!server)
}

/** A slider's bar: filled to its position, a knob at the end. */
function sliderBar(fraction: number, width: number): string {
  const at = Math.round(Math.max(0, Math.min(1, fraction)) * (width - 1))
  return '━'.repeat(at) + '●' + '─'.repeat(Math.max(0, width - 1 - at))
}

function since(at: number): string {
  const s = Math.max(0, Math.round((Date.now() - at) / 1000))
  return s < 90 ? `${s} s ago` : `${Math.round(s / 60)} min ago`
}

/** A label cut to `width` characters with an ellipsis, so a button never wraps its bracket. */
function fit(text: string, width: number): string {
  return text.length <= width ? text : `${text.slice(0, Math.max(1, width - 1))}…`
}

function formatState(state: string): string {
  const number = Number(state)
  if (state.trim() !== '' && Number.isFinite(number) && !Number.isInteger(number)) return String(Math.round(number * 100) / 100)
  return state.replace(/_/g, ' ')
}

function firstLine(text: string | null): string | null {
  return text ? (text.split('\n').find(line => line.trim()) ?? null) : null
}

/** The JSON body of a vome MCP reply, which ends with a `[vome-instance]` line. */
function parseJson(raw: string): Record<string, unknown> | null {
  const text = raw.replace(/\[vome-instance\][^\n]*/g, '')
  const start = text.search(/[[{]/)
  const end = Math.max(text.lastIndexOf('}'), text.lastIndexOf(']'))
  if (start < 0 || end <= start) return null
  try {
    const value = JSON.parse(text.slice(start, end + 1)) as unknown
    return value && typeof value === 'object' && !Array.isArray(value) ? (value as Record<string, unknown>) : null
  } catch {
    return null
  }
}

files.hooks/lovelace.ts:
// A Lovelace dashboard as the pane draws it: views of cards, each card a title
// and rows, each row an entity (with the control that suits it), a button with
// its action, or text. Pure: the config in, a model out, and the service call
// a press makes. Cards the pane cannot draw keep their entities, so a custom
// card still shows the things it is about.

export type ServiceCall = {
  domain: string
  service: string
  target?: { entity_id: string | string[] }
  data?: Record<string, unknown>
  /** Asked before it runs: "Wipe everything this fly has learned?" */
  confirm?: string
}

export type Row =
  | { kind: 'entity'; entity: string; name: string | null; icon?: string | null }
  | { kind: 'button'; name: string; icon: string | null; call: ServiceCall | null; entity: string | null }
  | { kind: 'text'; text: string }

export type Card = {
  /** Where it is, `v0/c3/c1`: stable across a save that changes other cards. */
  key: string
  type: string
  title: string | null
  rows: Row[]
  /** Markdown cards: their content, templates and all. */
  markdown: string | null
  /** History graphs: hours shown, and the entities graphed. */
  hours: number | null
  children: Card[]
  /** A card only Home Assistant can draw (custom:*, maps). */
  isForeign: boolean
  /** A picture card's camera, drawn from its frames. */
  camera: string | null
  /** Entities cards: whether the header has a switch for all of them (Home Assistant's default). */
  headerToggle: boolean
}

export type View = { title: string; path: string | null; cards: Card[] }

type Obj = Record<string, unknown>

const isObj = (value: unknown): value is Obj => !!value && typeof value === 'object' && !Array.isArray(value)
const str = (value: unknown): string | null => (typeof value === 'string' && value.trim() ? value : null)

/**
 * A title or name without the pictographs terminals disagree about the width of: those that
 * default to text presentation (🌡, 🎛, ☀, ❄…), which one terminal draws in one cell and another
 * in two, so everything after them on the row shifts and leaves stray borders. Emoji that are
 * always emoji (💡, 🔥) are kept.
 */
export function steady(text: string): string {
  return text.replace(/(?![\p{Emoji_Presentation}])\p{Extended_Pictographic}\uFE0F?\s*/gu, '').replace(/\uFE0F/g, '').trim() || text
}
const label = (value: unknown): string | null => {
  const s = str(value)
  return s ? steady(s) : null
}

export function viewsOf(config: unknown): View[] {
  if (!isObj(config) || !Array.isArray(config.views)) return []
  return config.views.filter(isObj).map((view, v) => {
    const sections = Array.isArray(view.sections) ? view.sections.filter(isObj).flatMap(section => (Array.isArray(section.cards) ? section.cards : [])) : []
    const cards = [...(Array.isArray(view.cards) ? view.cards : []), ...sections]
    return {
      title: label(view.title) ?? str(view.path) ?? `View ${v + 1}`,
      path: str(view.path),
      cards: cards.filter(isObj).map((card, c) => cardOf(card, `v${v}/c${c}`)),
    }
  })
}

function cardOf(card: Obj, key: string): Card {
  const type = str(card.type) ?? 'unknown'
  const base: Card = {
    key,
    type,
    title: label(card.title) ?? label(card.name),
    rows: [],
    markdown: null,
    hours: null,
    children: [],
    isForeign: false,
    camera: null,
    headerToggle: card.show_header_toggle !== false,
  }
  switch (type) {
    case 'vertical-stack':
    case 'horizontal-stack':
    case 'grid':
      return { ...base, children: (Array.isArray(card.cards) ? card.cards : []).filter(isObj).map((child, i) => cardOf(child, `${key}/c${i}`)) }
    case 'markdown':
      return { ...base, markdown: str(card.content) ?? '' }
    case 'entities':
    case 'glance':
      return { ...base, rows: (Array.isArray(card.entities) ? card.entities : []).map(rowOf).filter((row): row is Row => row !== null) }
    case 'history-graph':
    case 'statistics-graph':
      return {
        ...base,
        hours: typeof card.hours_to_show === 'number' ? card.hours_to_show : 24,
        rows: (Array.isArray(card.entities) ? card.entities : []).map(rowOf).filter((row): row is Row => row !== null),
      }
    case 'picture-entity':
    case 'picture-glance':
    case 'picture-elements': {
      const camera = [str(card.camera_image), str(card.entity)].find(e => e?.startsWith('camera.')) ?? null
      const named = (Array.isArray(card.entities) ? card.entities : []).map(e => (isObj(e) ? str(e.entity) : str(e))).filter((e): e is string => !!e)
      return { ...base, camera, title: base.title ?? (camera ? null : base.title), rows: named.map(entity => ({ kind: 'entity' as const, entity, name: null })), isForeign: !camera }
    }
    case 'button': {
      const entity = str(card.entity)
      const call = actionOf(card.tap_action, entity)
      // Its name is the button's label: not a title over it as well.
      return { ...base, title: null, rows: [{ kind: 'button', name: label(card.name) ?? entity ?? 'Button', icon: str(card.icon), call, entity }] }
    }
    case 'tile':
    case 'light':
    case 'thermostat':
    case 'sensor':
    case 'gauge':
    case 'entity':
    case 'humidifier':
    case 'media-control':
    case 'alarm-panel':
    case 'weather-forecast': {
      const entity = str(card.entity)
      return { ...base, rows: entity ? [{ kind: 'entity', entity, name: str(card.name), icon: str(card.icon) }] : [] }
    }
    default: {
      // A card the pane cannot draw: keep whatever entities it names.
      const named = [str(card.entity), ...(Array.isArray(card.entities) ? card.entities.map(e => (isObj(e) ? str(e.entity) : str(e))) : [])].filter((e): e is string => !!e)
      return { ...base, isForeign: true, rows: named.map(entity => ({ kind: 'entity' as const, entity, name: null })) }
    }
  }
}

function rowOf(row: unknown): Row | null {
  if (typeof row === 'string') return { kind: 'entity', entity: row, name: null }
  if (!isObj(row)) return null
  const entity = str(row.entity)
  if (row.type === 'button' || (!entity && row.tap_action)) {
    return { kind: 'button', name: str(row.name) ?? str(row.action_name) ?? 'Run', icon: str(row.icon), call: actionOf(row.tap_action, entity), entity }
  }
  if (row.type === 'section' || row.type === 'divider') return str(row.label) ? { kind: 'text', text: str(row.label)! } : null
  if (row.type === 'text' || row.type === 'attribute') return str(row.name) ? { kind: 'text', text: str(row.name)! } : null
  return entity ? { kind: 'entity', entity, name: str(row.name), icon: str(row.icon) } : null
}

/** A tap_action as the service call it makes; navigation, more-info and URLs are Home Assistant's own. */
export function actionOf(action: unknown, entity: string | null): ServiceCall | null {
  if (!isObj(action)) return entity ? toggleFor(entity) : null
  const kind = str(action.action)
  const confirm = isObj(action.confirmation) ? (str(action.confirmation.text) ?? 'Are you sure?') : action.confirmation === true ? 'Are you sure?' : undefined
  if (kind === 'toggle' && entity) {
    const call = toggleFor(entity)
    return call ? { ...call, ...(confirm ? { confirm } : {}) } : null
  }
  if (kind === 'perform-action' || kind === 'call-service') {
    const name = str(action.perform_action) ?? str(action.service)
    const [domain, service] = (name ?? '').split('.')
    if (!domain || !service) return null
    const target = isObj(action.target) && (typeof action.target.entity_id === 'string' || Array.isArray(action.target.entity_id))
      ? { entity_id: action.target.entity_id as string | string[] }
      : undefined
    const data = isObj(action.data) ? action.data : isObj(action.service_data) ? action.service_data : undefined
    return { domain, service, ...(target ? { target } : {}), ...(data ? { data } : {}), ...(confirm ? { confirm } : {}) }
  }
  return null
}

const TOGGLE_DOMAINS = new Set(['light', 'switch', 'fan', 'input_boolean', 'automation', 'siren', 'humidifier'])
const RUN_DOMAINS: Record<string, string> = { scene: 'turn_on', script: 'turn_on', button: 'press', input_button: 'press' }

/** What pressing an entity does: toggle the toggleable, run scenes and scripts, press buttons. */
export function toggleFor(entity: string): ServiceCall | null {
  const domain = entity.split('.')[0] ?? ''
  if (TOGGLE_DOMAINS.has(domain)) return { domain, service: 'toggle', target: { entity_id: entity } }
  if (RUN_DOMAINS[domain]) return { domain, service: RUN_DOMAINS[domain]!, target: { entity_id: entity } }
  return null
}

/** A step up or down for things with a value: input_number and number, a light's brightness, a thermostat's target. */
export function stepFor(entity: string, attributes: Obj, state: string, direction: 1 | -1): ServiceCall | null {
  const domain = entity.split('.')[0] ?? ''
  if (domain === 'input_number' || domain === 'number') {
    const step = typeof attributes.step === 'number' ? attributes.step : 1
    const min = typeof attributes.min === 'number' ? attributes.min : -Infinity
    const max = typeof attributes.max === 'number' ? attributes.max : Infinity
    const value = Math.min(max, Math.max(min, Number(state) + direction * step * stepScale(attributes)))
    return Number.isFinite(value) ? { domain, service: 'set_value', target: { entity_id: entity }, data: { value: round(value, step) } } : null
  }
  if (domain === 'light' && state === 'on') return { domain, service: 'turn_on', target: { entity_id: entity }, data: { brightness_step_pct: direction * 20 } }
  if (domain === 'climate') {
    const target = typeof attributes.temperature === 'number' ? attributes.temperature : null
    const step = typeof attributes.target_temp_step === 'number' ? attributes.target_temp_step : 0.5
    return target === null ? null : { domain, service: 'set_temperature', target: { entity_id: entity }, data: { temperature: round(target + direction * step, step) } }
  }
  if (domain === 'cover') return { domain, service: direction > 0 ? 'open_cover' : 'close_cover', target: { entity_id: entity } }
  return null
}

/** A slider with a hundred steps moves a tenth of its range a press: nobody presses + fifty times. */
function stepScale(attributes: Obj): number {
  const step = typeof attributes.step === 'number' ? attributes.step : 1
  const span = typeof attributes.max === 'number' && typeof attributes.min === 'number' ? attributes.max - attributes.min : 0
  return span > 0 && span / step > 20 ? Math.round(span / step / 10) : 1
}

function round(value: number, step: number): number {
  const places = Math.max(0, (String(step).split('.')[1] ?? '').length)
  return Number(value.toFixed(places))
}

/** Every entity a view shows, for the state reads. */
export function entitiesOf(cards: Card[]): string[] {
  const out = new Set<string>()
  const walk = (card: Card) => {
    for (const row of card.rows) if (row.kind !== 'text' && row.entity) out.add(row.entity)
    card.children.forEach(walk)
  }
  cards.forEach(walk)
  return [...out]
}

/** Cards a save added or changed, by key and content. */
export function changedCards(before: unknown, after: unknown): Set<string> {
  const flat = (config: unknown) => {
    const out = new Map<string, string>()
    if (!isObj(config) || !Array.isArray(config.views)) return out
    config.views.forEach((view, v) => {
      const cards = isObj(view) && Array.isArray(view.cards) ? view.cards : []
      cards.forEach((card, c) => out.set(`v${v}/c${c}`, JSON.stringify(card)))
    })
    return out
  }
  const old = flat(before)
  const now = flat(after)
  return new Set([...now].filter(([key, json]) => old.get(key) !== json).map(([key]) => key))
}

/** "▁▂▄▇" from a series of numbers, `width` characters wide. */
export function sparkline(values: number[], width: number): string {
  if (values.length === 0) return ''
  const blocks = '▁▂▃▄▅▆▇█'
  const step = values.length / width
  const picked = Array.from({ length: Math.min(width, values.length) }, (_, i) => values[Math.floor(i * Math.max(1, step))] ?? 0)
  const min = Math.min(...picked)
  const max = Math.max(...picked)
  return picked.map(v => blocks[max === min ? 3 : Math.round(((v - min) / (max - min)) * 7)]).join('')
}

/** A domain's glyph, single-width. */
export function iconFor(entity: string, state: string): string {
  const domain = entity.split('.')[0] ?? ''
  const on = state === 'on' || state === 'open' || state === 'home' || state === 'playing'
  switch (domain) {
    case 'light':
      return on ? '●' : '○'
    case 'switch':
    case 'input_boolean':
    case 'fan':
    case 'automation':
      return on ? '■' : '□'
    case 'binary_sensor':
      return on ? '◉' : '◌'
    case 'sensor':
    case 'input_number':
    case 'number':
      return '≈'
    case 'climate':
      return '❄'
    case 'cover':
      return '▤'
    case 'scene':
    case 'script':
      return '▶'
    case 'person':
    case 'device_tracker':
      return '☺'
    default:
      return '·'
  }
}

const DOT = [
  [0x01, 0x02, 0x04, 0x40],
  [0x08, 0x10, 0x20, 0x80],
]

/**
 * A line chart in braille, `width` characters by `rows` lines (2 x 4 dots a character): each
 * value a dot, joined to the next by a vertical run so a jump reads as a line, not a gap.
 */
export function brailleChart(values: number[], width: number, rows: number): string[] {
  const w = Math.max(2, width * 2)
  const h = Math.max(4, rows * 4)
  if (values.length === 0) return Array.from({ length: rows }, () => ' '.repeat(width))
  // One point per dot column: the average of the values that fall in it.
  const points = Array.from({ length: w }, (_, x) => {
    const from = Math.floor((x / w) * values.length)
    const to = Math.max(from + 1, Math.floor(((x + 1) / w) * values.length))
    const slice = values.slice(from, to)
    return slice.reduce((a, b) => a + b, 0) / slice.length
  })
  const min = Math.min(...points)
  const max = Math.max(...points)
  const yOf = (v: number) => (max === min ? Math.floor(h / 2) : Math.round((1 - (v - min) / (max - min)) * (h - 1)))
  const cells = Array.from({ length: rows }, () => new Array<number>(width).fill(0))
  const dot = (x: number, y: number) => {
    const row = Math.floor(y / 4)
    const col = Math.floor(x / 2)
    if (row >= 0 && row < rows && col >= 0 && col < width) cells[row]![col]! |= DOT[x % 2]![y % 4]!
  }
  let last: number | null = null
  points.forEach((v, x) => {
    const y = yOf(v)
    if (last !== null) for (let k = Math.min(last, y); k <= Math.max(last, y); k++) dot(x, k)
    dot(x, y)
    last = y
  })
  return cells.map(row => row.map(bits => String.fromCharCode(0x2800 + bits)).join(''))
}

/** Home Assistant's mdi icons as emoji that draw two cells wide everywhere (no variation selectors). */
const MDI: Array<[RegExp, string]> = [
  [/lightbulb|lamp|ceiling-light|light-recessed|led/, '💡'],
  [/power-socket|power-plug|outlet/, '🔌'],
  [/water|humidity|drop/, '💧'],
  [/motion|walk|run|human-male|account-arrow/, '🚶'],
  [/door/, '🚪'],
  [/window|blinds|curtain|shutter/, '🪟'],
  [/fan/, '🌀'],
  [/lock-open/, '🔓'],
  [/lock/, '🔒'],
  [/garage|car/, '🚗'],
  [/home|house/, '🏠'],
  [/account|person|human|face/, '👤'],
  [/battery/, '🔋'],
  [/fire|radiator|heat|flame/, '🔥'],
  [/snowflake|ice|freezer/, '🧊'],
  [/television|tv/, '📺'],
  [/speaker|music|play/, '🎵'],
  [/bell|alarm/, '🔔'],
  [/camera|cctv|cam/, '📷'],
  [/candy|food/, '🍬'],
  [/hand/, '✋'],
  [/delete|broom|sweep|trash/, '🧹'],
  [/butterfly|bug|fly/, '🪰'],
  [/brain/, '🧠'],
  [/radar|wifi|antenna|signal/, '📡'],
  [/chart|graph|trending/, '📈'],
  [/flash|lightning|power|energy|meter-electric/, '⚡'],
  [/weather-sunny|sun/, '🌞'],
  [/moon|night|sleep/, '🌙'],
  [/robot|auto/, '🤖'],
  // A thermometer emoji is text-presentation: terminals draw it one cell or two, and the row shifts.
  [/thermometer|temperature/, '🔥'],
]

/** The picture an entity is drawn with: its own mdi icon, else what kind of thing it is. */
export function glyphFor(entity: string, attributes: Record<string, unknown>, icon?: string | null): string {
  const mdi = (icon ?? (typeof attributes.icon === 'string' ? attributes.icon : '')).replace(/^mdi:/, '')
  if (mdi) for (const [pattern, glyph] of MDI) if (pattern.test(mdi)) return glyph
  const domain = entity.split('.')[0] ?? ''
  const kind = typeof attributes.device_class === 'string' ? attributes.device_class : ''
  switch (domain) {
    case 'light':
      return '💡'
    case 'switch':
      return '🔌'
    case 'fan':
      return '🌀'
    case 'lock':
      return '🔒'
    case 'cover':
      return '🪟'
    case 'climate':
    case 'water_heater':
      return '🔥'
    case 'person':
    case 'device_tracker':
      return '👤'
    case 'media_player':
      return '🎵'
    case 'camera':
      return '📷'
    case 'automation':
      return '🤖'
    case 'scene':
      return '🎬'
    case 'script':
      return '📜'
    case 'input_boolean':
    case 'button':
    case 'input_button':
      return '🔘'
    case 'input_number':
    case 'number':
      return '🔢'
    case 'binary_sensor':
      return /occupancy|motion|presence/.test(kind) ? '🚶' : /door|garage/.test(kind) ? '🚪' : /window/.test(kind) ? '🪟' : /smoke|heat/.test(kind) ? '🔥' : /moisture/.test(kind) ? '💧' : '🔵'
    case 'sensor':
      return /temperature/.test(kind) ? '🔥' : /humidity|moisture/.test(kind) ? '💧' : /battery/.test(kind) ? '🔋' : /power|energy|current|voltage/.test(kind) ? '⚡' : /illuminance/.test(kind) ? '🌞' : /distance/.test(kind) ? '📏' : '📊'
    default:
      return '🔵'
  }
}

/**
 * A lit light's glow, as a background for its row: the light's own colour (or warm white), mixed
 * into the dark panel by how bright it is. Null for anything that is not a light that is on.
 */
export function glowFor(entity: string, state: string, attributes: Record<string, unknown>): string | null {
  if (!entity.startsWith('light.') || state !== 'on') return null
  const rgb = Array.isArray(attributes.rgb_color) && attributes.rgb_color.length === 3 ? (attributes.rgb_color as number[]) : [255, 196, 96]
  const level = typeof attributes.brightness === 'number' ? attributes.brightness / 255 : 1
  const mix = 0.18 + 0.4 * level
  const base = [24, 26, 32]
  const hex = rgb.map((c, i) => Math.round(base[i]! + (c - base[i]!) * mix).toString(16).padStart(2, '0')).join('')
  return `#${hex}`
}

/** A lit light's colour for its state text: its own, or warm white. */
export function lightColour(attributes: Record<string, unknown>): string {
  const rgb = Array.isArray(attributes.rgb_color) && attributes.rgb_color.length === 3 ? (attributes.rgb_color as number[]) : [255, 204, 102]
  return `#${rgb.map(c => Math.round(c).toString(16).padStart(2, '0')).join('')}`
}


/**
 * A picture in half blocks for a Raster: two pixels a cell, the upper one the
 * foreground of an upper half block and the lower one its background. `rgb` is
 * 3 bytes a pixel, `width` x `height`; the cells are 12 bytes each (code point,
 * foreground, background), base64, as a Raster takes them.
 */
export function halfBlocks(rgb: Uint8Array, width: number, height: number): { cells: string; columns: number; rows: number } {
  const rows = Math.ceil(height / 2)
  const bytes = new Uint8Array(width * rows * 12)
  const view = new DataView(bytes.buffer)
  const at = (x: number, y: number) => {
    if (y >= height) return 0x000000
    const i = (y * width + x) * 3
    return ((rgb[i] ?? 0) << 16) | ((rgb[i + 1] ?? 0) << 8) | (rgb[i + 2] ?? 0)
  }
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < width; c++) {
      const cell = (r * width + c) * 12
      view.setUint32(cell, 0x2580, true)
      view.setUint32(cell + 4, at(c, r * 2), true)
      view.setUint32(cell + 8, at(c, r * 2 + 1), true)
    }
  }
  let out = ''
  const A = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
  for (let i = 0; i < bytes.length; i += 3) {
    const n = ((bytes[i] ?? 0) << 16) | ((bytes[i + 1] ?? 0) << 8) | (bytes[i + 2] ?? 0)
    out += A[(n >> 18) & 63]! + A[(n >> 12) & 63]!
    out += i + 1 < bytes.length ? A[(n >> 6) & 63]! : '='
    out += i + 2 < bytes.length ? A[n & 63]! : '='
  }
  return { cells: out, columns: width, rows }
}

/** base64 to bytes, without a Buffer. */
export function fromBase64(text: string): Uint8Array {
  const A = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
  const clean = text.replace(/[^A-Za-z0-9+/]/g, '')
  const out = new Uint8Array(Math.floor((clean.length * 3) / 4))
  let o = 0
  for (let i = 0; i < clean.length; i += 4) {
    const n = (A.indexOf(clean[i]!) << 18) | (A.indexOf(clean[i + 1] ?? 'A') << 12) | (A.indexOf(clean[i + 2] ?? 'A') << 6) | A.indexOf(clean[i + 3] ?? 'A')
    if (o < out.length) out[o++] = (n >> 16) & 255
    if (o < out.length) out[o++] = (n >> 8) & 255
    if (o < out.length) out[o++] = n & 255
  }
  return out
}

/**
 * Every read the pane makes in the background, all of them read-only: what auto mode needs
 * allowed by name. Kept beside the calls; a tool the pane starts using must be added here, or the
 * box asking for permission names the wrong lines (it missed the snapshot, watch and camera reads).
 */
export const READS = [
  'ha_view_snapshot',
  'ha_watch_states',
  'ha_camera_frame',
  'ha_get_state',
  'ha_render_template',
  'ha_get_history',
  'ha_get_dashboard',
  'ha_list_dashboards',
]

